sect2.programlisting:
Vehicles := DATASET('vehicles',
     {STRING2 st,
      STRING20 city,
      STRING20 lname,
      UNSIGNED8 filepos{VIRTUAL(fileposition)}},
     FLAT);
BUILD(Vehicles,{lname,filepos},'vkey::lname');
 //build key into Vehicles dataset on last name

sect2.para:
[attrname
    := ]
    BUILD(baserecset, keys, payload, indexfile [, options ] );

sect2.programlisting:
Vehicles := DATASET('vehicles',
     {STRING2 st,
      STRING20 city,
      STRING20 lname,
      UNSIGNED8 filepos{VIRTUAL(fileposition)}},
      FLAT);
BUILD(Vehicles,{st,city},{lname},'vkey::st.city1');
//build key into Vehicles dataset on state and city
//payload the last name

//same index build using non-inline RECORD structures

SearchTerms := RECORD
  Vehicles.st;
  Vehicles.city;
END; 
Payload := RECORD
  Vehicles.lname;
END; 
BUILD(Vehicles,SearchTerms,Payload,'vkey::st.city2');

sect2.para:
[attrname
    := ] BUILD( indexdef
    [,indexfile] [,
    options ]
    );

sect2.programlisting:
nameKey := INDEX(mainTable,{surname,forename,filepos},'name.idx');
BUILD(nameKey); //gets all info from the INDEX definition

// BUILDing a MERGEd index
BUILD(MERGE(idx1,idx2,'~idx::MergedIndex');

sect2.para:
[attrname
    := ] BUILD( indexdef, dataset,
    [, options
    ] );

para.programlisting:
//usual way to BUILD an INDEX:
ds1 = DATASET(100, TRANSFORM({ UNSIGNED id }, SELF.id := COUNTER));
i1 := INDEX(ds1, { id }, 'myIndex'); //specifies the dataset to always use
BUILD(i1);

//Separated way to BUILD an INDEX:
ds2 = DATASET(100, TRANSFORM({ UNSIGNED id }, SELF.id := COUNTER));
i2 := INDEX({ UNSIGNED id }, 'myIndex');
BUILD(i2, ds2);       //builds the i2 INDEX from the ds2 dataset

sect2.programlisting:
NamesRec := RECORD
  INTEGER1  NameID;
  STRING20  FName;
  STRING20  LName;
END;
FilterLibIface1(DATASET(namesRec) ds, STRING search) := INTERFACE
  EXPORT DATASET(namesRec) matches;
  EXPORT DATASET(namesRec) others;
END;

FilterDsLib1(DATASET(namesRec) ds, STRING search) :=
      MODULE,LIBRARY(FilterLibIface1)
  EXPORT matches := ds(Lname  = search);
  EXPORT others  := ds(Lname != search);
END;
#WORKUNIT('name','Ppass.FilterDsLib')
BUILD(FilterDsLib1);

Vehicles := DATASET('vehicles',
          {STRING2 st,STRING20 city,STRING20 lname},FLAT);

SearchTerms := RECORD
  Vehicles.st;
  Vehicles.city;
END; 
Payload     := RECORD
  Vehicles.lname;
END; 
VehicleKey := INDEX(Vehicles,SearchTerms,Payload,'vkey::st.city',
                    COMPRESSED('inplace:lz4shc,compressopt(hclevel=9,
                                                           maxcompression=25,
                                                           maxrecompress=4)'));
BUILD(VehicleKey);
